mapper.select:
SELECT 
FROM medication_log l
JOIN elder e ON e.id = l.elder_id
WHERE l.elder_id = #{elderId} AND l.take_date = #{takeDate}
AND e.deleted = 0 AND e.owner_id = #{ownerId}
ORDER BY l.remind_time ASC, l.id ASC

SELECT 
FROM medication_log l
JOIN elder e ON e.id = l.elder_id
WHERE l.elder_id = #{elderId} AND l.take_date BETWEEN #{from} AND #{to}
AND e.deleted = 0 AND e.owner_id = #{ownerId}
ORDER BY l.take_date DESC, l.remind_time ASC, l.id ASC

SELECT 
FROM medication_log l
JOIN elder e ON e.id = l.elder_id
WHERE l.plan_id = #{planId} AND l.take_date = #{takeDate} AND l.remind_time = #{remindTime}
AND e.deleted = 0 AND e.owner_id = #{ownerId}

SELECT COUNT(*)
FROM medication_log l
JOIN elder e ON e.id = l.elder_id
WHERE l.elder_id = #{elderId}
AND l.take_date BETWEEN #{from} AND #{to}
AND l.status = #{status}
AND e.deleted = 0 AND e.owner_id = #{ownerId}

mapper.delete:
DELETE l FROM medication_log l
JOIN elder e ON e.id = l.elder_id
WHERE l.id = #{id} AND e.owner_id = #{ownerId}
